"""
This library executed commands on remote machines over ssh/telnet
    === testcase_variables ===
    | *"remote_commands"* : {
    |	_*"command_section_tc1_uc1"*_: {            User defined profile name
    |    *"objcli show_version"*: "FTM_L18A_SR18A_CB18A_5G18A_W19_G19_2018",
    |       command to be executed: value to be verified
    |    *"cd /user/${bts['user']}"*  If verification is not needed just specify the command.
    |       Variables can be used in cmds
    |	},
    | }
"""
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection


def setup_remote_access(**kwargs):
    """
       _*Setup Remote Access*_  keyword can be used to establish a session with a remote host.

       *Usage*:
       Setup Remote Access <remote_device> <timeout> <alias>

       | *arguments* | *default value* | *comment* |
       | *remote_device* | Section name in test line config json file which contains details |  |
       |                 | of host such as ip, username, password, prompt(if telnet). |  |
       | *timeout* | 30 | timeout value. |
       | *alias* | default | name of execution context |
       | *ip* | host ip | This argument takes precedence over the ip address specified in the |
       |      |         | remote_device section |
       | *user* | login user name | This argument takes precedence over the user provided in |
       |        |                 | the remote_device section |
       | *password* | login password | This argument takes precedence over the password |
       |            |                | provided in the remote_device section |
       | *private_key* |  | Location (absolute path) of custom private key file |
       | *user_param_path* |  | Parameter path for admin to upload the keys to eNodeB.Applicable |
       |                   |  | only for eNB |
       | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |

       *Below parameters are applicable only for eNB and if LTE2647(Root user) is enabled*
       | *root_username* | Username for root authentication | Applicable only for eNb if LTE2647 feature is enabled |
       | *root_password* | Password for root authentication | Applicable only for eNb if LTE2647 feature is enabled |
       | *root_private_key* | Private Key file location  to gain root access | Applicable only for eNb if LTE2647
       |  | feature is enabled |

       *Example*
       | *keyword* | *arguments* |*timeout* |*alias* |
       | *Setup Remote Access* | *remote_device=sec1.sec2.sec3* | 30 | default |
       | *Setup Remote Access* | *remote_device=sec1* |  |  |

       *Two user login  Examples*

       | *Setup Remote Access* | *bts*  *private_key=/home/ute/service_user* |
       |    | *user_param_path=SECADM-1:serviceUserPublicKeys* |
       |    | *root_username=toor4nsn* *root_private_key=/home/ute/root_user* |
       |    | *root_user_param_path=SECADM-1:rootUserPublicKeys* |
       | *Setup Remote Access* | *bts* *private_key=/home/ute/service_user* |
       |    | *user_param_path=SECADM-1:serviceUserPublicKeys* *root_username=toor4nsn* |
       |    | *root_private_key=/home/ute/root_user* |
       |    | *root_user_param_path=SECADM-1:rootUserPublicKeys* |
       | *Setup Remote Access* | *ip=192.168.255.129* *user=serviceuser* |
       |     | *password=Pl(FzaYj5~c5;q* |
       | *Setup Remote Access* | *ip=192.168.255.129* *user=serviceuser* |
       |    | *private_key=/home/ute/service_user* |
       |    | *user_param_path=SECADM-1:serviceUserPublicKeys* |
       |    | *root_username=toor4nsn*  *root_private_key=/home/ute/root_user* |
       |    | *root_user_param_path=SECADM-1:rootUserPublicKeys* |

       *Single User login with key*

       | *Setup Remote Access* | *ip=192.168.255.129* | *user=toor4nsn* | *private_key=/home/ute/test* |
       |  | *root_user_param_path=SECADM-1:rootUserPublicKeys* |

       *Note* ::
            In testline_config.json file, add a key called "session_type". Set its value to 'SSH' or 'TELNET' based
            on the type of connection. If this key is not found then, the type of connection is cosidered as SSH by
            default.

    """
    RemoteConnection().setup_remote_access(**kwargs)


def connect_to_hop(**kwargs):
    """
    Connect to hop, SSH/SFT to given remote device.
    Executes command with reference to given alias.
    If SSH is alreday done to a host then use same alias to do second SSH to another host via previously connected host

     *Usage*:
        Connect To Hop Command <command> <alias> <prompt>

    *Parameters:*
    | *Name* | *Default* | *Comment* |
    | remote_device | Mandatory | Command to execute |
    | session_type | 'SSH' | type of connection ssh/sftp to perform on given remote device |
    | alias | 'Default' | name of execution context |
    | prompt | '$' | string, send expected prompt. Default '$' |

    *Return*: Response received from the channel and error(if any)

    *Raises*: SSHException: raises an exception

    """
    return RemoteConnection().connect_to_hop(**kwargs)


def exit_hop_connection(**kwargs):
    """
    Exits connection that was made using "Connect To Hop" keyword.

     *Usage*:
        Exit Hop Connection <alias> <prompt>

    *Parameters:*
    | *Name* | *Default* | *Comment* |
    | alias | 'Default' | name of execution context |
    | prompt | '$' | string, send expected prompt. Default '$' |

    *Return*: Response received from the channel and error(if any)

    *Raises*: SSHException: raises an exception

    """
    return RemoteConnection().exit_hop_connection(**kwargs)


def remote_command_execute(**kwargs):
    """
        This keyword can be used to only execute a command or
        execute and verify output of a command in a remote host that supports SSH.

        *Parameter:*
        *Common*
        | *arguments* | *comment* | *default value* |
        | *kwargs* | Set of arguments required to execute the key word.Details given below. |

        *Kwarg arguments required for execution of command and verification of its output.*
        | *Kwarg arguments* | *comment* | *default value* |
        | *command_section* | Name of the section in the testcase_config json file which |  |
        |                   | contains the commands. |  |
        | *alias* |  name of execution context | default |
        | *continue_on_failure* | used to decide if execution must continue when command |  |
        |                       | execution fails or expected result is not found | ${True} |
        | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |

        *command_section format is defined at the top of this file*

        *Kwarg arguments required for only execution of command.*
        | *Kwarg arguments* | *comment* | *default value* |
        | *command* | command to be executed on remote host. | |
        | *return_rc* | should the keyword return status of command execution. |  |
        |             | Takes boolean ${True} or ${False} as its value| ${False} |
        | *alias* |  name of execution context | default |
        | *pty* | False | boolean, True or False |
        | *continue_on_failure* | used to decide if execution must continue when command |  |
        |                       | execution fails or expected result is not found | ${True} |


        *Usage*:
        Remote Command Execute <kwargs>

        *Example*
        | *keyword* | *command_section* |
        | *Remote Command Execute* | *command_section=cmd_sec1.cmd_sec2.cmd_sec3*  |
        | *Remote Command Execute* | *command_section=cmd_sec* *alias=default* *continue_on_failure=False* |
        | *Remote Command Execute* | *command=echo Hello* *return_rc = ${True}* * alias=default* |

    """
    return RemoteConnection().remote_command_execute(**kwargs)


def execute_remote_command(**kwargs):
    """
    *NOTE:* This keyword is deprecated. Please consider to use 'Remote Command Execute' keyword instead.

    Executes command with reference to given alias

     *Usage*:
        Execute Command <command> <alias> <wait_for_response> <timeout>

    | *arguments* | *default value* | *comment* |
    | command | Mandatory | Command to execute |
    | alias | Mandatory | name of execution context |
    | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |
    | timeout | 2 | timeout value |

    *Return*: Response received from the channel and error(if any)

    *Exceptions*: SSHException: raises an exception
    """
    raise DeprecationWarning("Execute Remote Command is now deprecated. Kindly use Remote Command Execute instead.")


def execute_interactive_remote_command(**kwargs):
    """
    Executes command on shell with reference to given alias

     *Usage*:
        Execute Command On Shell <command> <alias> <wait_for_response> <timeout>

    | *arguments* | *default value* | *comment* |
    | command | Mandatory | Command to execute |
    | alias | Mandatory | name of execution context |
    | exit_prompt | None | string, if exit_prompt is given keyword waits untill exit prompt is seen in output. |
    |  |  | If exit_prompt is not passed, keyword just returns the command output |
    | return_rc | False | returns error output |
    | timeout | 2 | timeout value |

    *Return*: Response received from the channel and error(if any)

    *Exceptions*: SSHException: raises an exception
    """
    return RemoteConnection().execute_command_on_shell(**kwargs)


def get_file_from_remote_host(source, destination, alias='default'):
    """
       _*Get File From Remote Host*_  gets file from a remote host.

       *Usage*:
        Get File <source> <destination> <alias>


        *Common*
       | *arguments* | *comment* | *default value* |
       | *source* |  location of file in remote host |  |
       | *destination* |  location on working system where file is to be placed |  |
       | *alias* |  name of execution context | default |


       *Example*
       | *keyword* | *source* | *destination* | *alias* |
       | *Get File* | /home/lte | /home/lte/dir1 | default1 |

    """
    return RemoteConnection().get_file(source=source, destination=destination, alias=alias)


def put_file_to_remote_host(source, destination, alias='default'):
    """

    _*Put File To Remote Host*_  puts file to a remote host.

       *Usage*:
        Put File <source> <destination> <alias>

        *Common*
       | *arguments* | *comment* | *default value* |
       | *source* |  location of file in working system where file is present |  |
       | *destination* |  location on remote system where file is to be placed |  |
       | *alias* |  name of execution context | default |

       *Example*
       | *keyword* | *source* | *destination* | *alias* |
       | *Put File To Remote Host* | /home/lte | /home/lte/dir1 | default1 |

    """
    RemoteConnection().put_file(source=source, destination=destination, alias=alias)


def teardown_remote_access(alias='default'):
    """
       _*Teardown Remote Access*_  keyword can be used to end a session with a remote host.

       *Usage*:
        Tear Down Access <alias>

       *Common*
       | *arguments* | *comment* | *default value* |
       | *alias* |  name of execution context | default |
       | rat | At least one of the RATs is Mandatory eg. lte/wcdma/gsm etc. | common |


       *Example*
       | *keyword* | *alias* |
       | *Teardown Remote Access* | |
       | *Teardown Remote Access* | default1 |

    """
    RemoteConnection().teardown_remote_access(alias)
